<?php
namespace FurMedia\Cache;
class FrontPanel {
 public static function token(Vault $vault,$session,$generation,$expires){return $expires.'.'.$vault->sign($session.'|'.$generation.'|'.$expires);}
 public static function verify(Vault $vault,$token,$session,$generation){$p=explode('.',$token);return count($p)===2&&ctype_digit($p[0])&&(int)$p[0]>=time()&&(int)$p[0]<=time()+600&&hash_equals(self::token($vault,$session,$generation,$p[0]),$token);}
 public static function html($endpoint,$token,$ttl,array $s){$e=function($v){return htmlspecialchars($v,ENT_QUOTES,'UTF-8');};$side=$s['panel_position']==='left'?'left':'right';return '<aside id="skynova-cache-panel" style="position:fixed;bottom:12px;'.$side.':12px;z-index:99999;background:'.$e($s['panel_color']).';color:'.$e($s['panel_text']).';font:'.$s['panel_font'].'px sans-serif;padding:12px;border-radius:8px"><strong>SkyNova · diagnostic</strong><div>Expiră în <span data-skynova-count>'.(int)$ttl.'</span>s</div><button type="button">Golește cache-ul acestei sesiuni</button><span data-skynova-result></span></aside><script>(function(){var p=document.getElementById("skynova-cache-panel"),n='.(int)$ttl.';setInterval(function(){p.querySelector("[data-skynova-count]").textContent=Math.max(0,--n)},1000);p.querySelector("button").onclick=function(){this.disabled=true;fetch('.json_encode($endpoint).',{method:"POST",credentials:"same-origin",cache:"no-store",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:"panel_token="+encodeURIComponent('.json_encode($token).')}).then(function(r){if(!r.ok)throw Error();return r.json()}).then(function(){location.reload()}).catch(function(){p.querySelector("[data-skynova-result]").textContent=" Sesiune expirată";p.querySelector("button").disabled=false})}})();</script>';}
}
